# تعليمات عمل إضافية (0076) — نفس بنية 0058
import json
def q(s): return "$w$" + s + "$w$"
def sec(key, title, body, **kw): d = {'key': key, 'title': title, 'body': body}; d.update(kw); return d
def bl(items): return '\n'.join('- ' + x for x in items)
def steps_tbl(rows): return '| # | الخطوة | التحقق |\n' + '\n'.join(f'| {i+1} | {a} | {b} |' for i, (a, b) in enumerate(rows))
def tbl(head, rows): return '| ' + ' | '.join(head) + ' |\n' + '\n'.join('| ' + ' | '.join(r) + ' |' for r in rows)
def T(ar, en, ur, bn, hi, tl): return {'ar': ar, 'en': en, 'ur': ur, 'bn': bn, 'hi': hi, 'tl': tl}

W = []
def wi(code, unit, cat, icon, title, audience, purpose, safety, tools, steps, freq, accept, donts, procs, checklist=None, card=None):
  secs = [sec('purpose', 'الغرض والنطاق', purpose), sec('safety', 'السلامة ومعدات الوقاية', bl(safety)), sec('tools', 'الأدوات والمواد', bl(tools)),
          sec('steps', 'خطوات التنفيذ', steps_tbl(steps)), sec('freq', 'التكرار', tbl(['العمل', 'التكرار'], freq)), sec('accept', 'معايير القبول', bl(accept)),
          sec('donts', 'ممنوعات', bl(donts)),
          sec('checklist', 'قائمة التحقق في المنصة', 'هذه البنود تُستخدم قائمة تحقق في خطط الصيانة والجولات بالمنصة؛ لا يُغلق أمر العمل قبل إكمالها، ويُرفق بها صور قبل وبعد عند الحاجة.', auto='checklist'),
          sec('refs', 'المراجع والإجراءات', 'الإجراءات والقواعد والمعايير الحاكمة لهذا العمل.', auto='procs', procs=' · '.join(procs))]
  W.append(dict(code=code, unit=unit, cat=cat, icon=icon, title=title, audience=audience, sections=secs, checklist=checklist or [a for a, b in steps][:10], card=card or {}))

